// ---------- time helpers ----------
function etNow() {
  return new Date(
    new Date().toLocaleString("en-US", { timeZone: "America/New_York" })
  );
}

function todayLabel() {
  return etNow().toLocaleDateString("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}

function todayISO() {
  const d = etNow();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${d.getFullYear()}-${m}-${day}`;
}

// Splits a stored UTC ISO timestamp into local <input type="date">/<input
// type="time"> values (the inverse of `new Date(`${date}T${time}:00`)`).
function isoToLocalParts(iso) {
  const d = new Date(iso);
  const pad = (n) => String(n).padStart(2, "0");
  return {
    date: `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`,
    time: `${pad(d.getHours())}:${pad(d.getMinutes())}`,
  };
}

const DAY_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri"];

function tradingWeek() {
  const now = etNow();
  const dow = now.getDay();
  const monday = new Date(now);
  const offset = dow === 0 ? 1 : dow === 6 ? 2 : 1 - dow;
  monday.setDate(monday.getDate() + offset);
  monday.setHours(0, 0, 0, 0);
  return DAY_LABELS.map((label, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return { label, date: d };
  });
}

function monthYearText() {
  const week = tradingWeek();
  return week[0].date.toLocaleDateString("en-US", {
    month: "long",
    year: "numeric",
  });
}

function isToday(date) {
  const now = etNow();
  return (
    date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate()
  );
}

// ---------- API helpers ----------
function parseJsonLoose(text) {
  const cleaned = text.replace(/```json|```/g, "").trim();
  const start = cleaned.indexOf("{");
  if (start === -1) throw new Error("No JSON found in response");
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < cleaned.length; i++) {
    const ch = cleaned[i];
    if (escaped) {
      escaped = false;
    } else if (ch === "\\" && inString) {
      escaped = true;
    } else if (ch === '"') {
      inString = !inString;
    } else if (!inString) {
      if (ch === "{") depth++;
      else if (ch === "}") {
        depth--;
        if (depth === 0) return JSON.parse(cleaned.slice(start, i + 1));
      }
    }
  }
  throw new Error("Incomplete JSON in response");
}

// ---------- clock ----------
function useEtClock() {
  const [now, setNow] = useState(etNow());
  useEffect(() => {
    const id = setInterval(() => setNow(etNow()), 1000);
    return () => clearInterval(id);
  }, []);
  return now;
}

function openCountdown(now) {
  const open = new Date(now);
  open.setHours(9, 30, 0, 0);
  const close = new Date(now);
  close.setHours(16, 0, 0, 0);
  const day = now.getDay();
  if (day === 0 || day === 6) return { label: "WEEKEND", tone: T.faint };
  if (now >= open && now < close) {
    return { label: `OPEN · closes in ${fmtDur(close - now)}`, tone: T.green };
  }
  if (now < open) {
    return { label: `opens in ${fmtDur(open - now)}`, tone: T.amber };
  }
  return { label: "CLOSED", tone: T.faint };
}

function fmtDur(ms) {
  const s = Math.floor(ms / 1000);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  return h > 0
    ? `${h}h ${String(m).padStart(2, "0")}m`
    : `${m}m ${String(sec).padStart(2, "0")}s`;
}

