// ---------- Raw Data tab ----------
function RawDataTab() {
  const [dayBars, setDayBars] = useState(null);
  const [dayIndex, setDayIndex] = useState(0);
  const [loadState, setLoadState] = useState("loading");

  useEffect(() => {
    (async () => {
      try {
        const rows = await fetchAllRows("bars", { orderBy: "ts" });
        const featureColSet = new Set();
        const byDay = new Map();
        for (const row of rows) {
          const day = row.ts.slice(0, 10);
          if (!byDay.has(day)) byDay.set(day, []);
          const features = row.features || {};
          Object.keys(features).forEach((k) => featureColSet.add(k));
          byDay.get(day).push({
            ts: row.ts, o: row.open, h: row.high, l: row.low, c: row.close, v: row.volume, features,
          });
        }
        const days = [...byDay.keys()].sort();
        setDayBars({ days, byDay, featureCols: [...featureColSet] });
        setDayIndex(days.length - 1);
      } catch {
        // no bar data available
      }
      setLoadState("ready");
    })();
  }, []);

  if (loadState === "loading") {
    return (
      <div style={{ color: T.faint, fontFamily: T.mono, fontSize: 12 }}>
        Loading…
      </div>
    );
  }

  if (!dayBars || dayBars.days.length === 0) {
    return (
      <div style={{ color: T.dim, fontSize: 13 }}>
        No bar data found. Run the pipeline to populate the bars table.
      </div>
    );
  }

  const day = dayBars.days[dayIndex];
  const bars = dayBars.byDay.get(day) || [];
  const navBtn = (disabled) => ({
    ...retryBtn,
    padding: "4px 10px",
    opacity: disabled ? 0.35 : 1,
    cursor: disabled ? "default" : "pointer",
  });
  const fmtTime = (ts) =>
    new Date(ts).toLocaleTimeString("en-US", {
      timeZone: "America/New_York",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
  const th = {
    position: "sticky",
    top: 0,
    background: T.panel,
    color: T.dim,
    fontFamily: T.mono,
    fontSize: 11,
    fontWeight: 400,
    textAlign: "right",
    padding: "6px 12px",
    borderBottom: `1px solid ${T.panelEdge}`,
  };
  const td = {
    fontFamily: T.mono,
    fontSize: 12,
    color: T.ink,
    textAlign: "right",
    padding: "4px 12px",
    borderBottom: `1px solid ${T.panelEdge}`,
  };

  return (
    <div>
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          alignItems: "center",
          gap: 10,
          marginBottom: 14,
        }}
      >
        <button
          onClick={() => setDayIndex((i) => Math.max(0, i - 1))}
          disabled={dayIndex === 0}
          style={navBtn(dayIndex === 0)}
        >
          ← Prev
        </button>
        <span
          style={{
            fontFamily: T.mono,
            fontSize: 12,
            color: T.ink,
            minWidth: 90,
            textAlign: "center",
          }}
        >
          {day}
        </span>
        <button
          onClick={() => setDayIndex((i) => Math.min(dayBars.days.length - 1, i + 1))}
          disabled={dayIndex === dayBars.days.length - 1}
          style={navBtn(dayIndex === dayBars.days.length - 1)}
        >
          Next →
        </button>
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.faint, marginLeft: "auto" }}>
          {bars.length} bars
        </span>
      </div>

      <div
        style={{
          background: T.panel,
          border: `1px solid ${T.panelEdge}`,
          borderRadius: 10,
          maxHeight: 560,
          overflow: "auto",
        }}
      >
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th style={{ ...th, textAlign: "left" }}>Time (ET)</th>
              <th style={th}>Open</th>
              <th style={th}>High</th>
              <th style={th}>Low</th>
              <th style={th}>Close</th>
              <th style={th}>Volume</th>
              {dayBars.featureCols.map((f) => (
                <th key={f} style={{ ...th, whiteSpace: "nowrap" }}>
                  {fLabel(f)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {bars.map((b) => (
              <tr key={b.ts}>
                <td style={{ ...td, textAlign: "left", color: T.dim }}>{fmtTime(b.ts)}</td>
                <td style={td}>{b.o.toFixed(2)}</td>
                <td style={td}>{b.h.toFixed(2)}</td>
                <td style={td}>{b.l.toFixed(2)}</td>
                <td style={{ ...td, color: b.c >= b.o ? T.green : T.red }}>{b.c.toFixed(2)}</td>
                <td style={td}>{b.v.toLocaleString()}</td>
                {dayBars.featureCols.map((f) => {
                  const v = b.features[f];
                  return (
                    <td key={f} style={{ ...td, color: T.dim }}>
                      {v === null || v === undefined ? "—" : v.toFixed(2)}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ---------- model tab ----------
// Synthesized daily by the Claude Code routine (regression + Training Data
// examples) directly into entry_models — this tab is read-only display.

function fmtRuleValue(v) {
  if (v === null || v === undefined || v === "") return "n/a";
  const n = Number(v);
  return Number.isFinite(n) ? n.toFixed(2) : String(v);
}

// ---------- rule evaluation (drives the Preview) ----------
// Evaluated against the `features` jsonb the pipeline already stored on each
// bar, so this never re-derives indicators in JS — the values here are exactly
// what compute_features() produced. Note this makes the preview the canonical
// reading of the rules; the PineScript recomputes features from Pine primitives
// and knowingly diverges (vol_z is approximated, premarket may be unavailable),
// so small disagreements with TradingView are expected, not bugs.
const RULE_OPS = {
  "<": (a, b) => a < b,
  "<=": (a, b) => a <= b,
  ">": (a, b) => a > b,
  ">=": (a, b) => a >= b,
};

function ruleHolds(features, rule) {
  const fn = RULE_OPS[rule.op];
  const v = features ? features[rule.feature] : undefined;
  // a missing feature (null in the jsonb — e.g. premarket levels before enough
  // days accumulated) fails the rule rather than firing a signal on no evidence
  if (!fn || v === null || v === undefined) return false;
  return fn(Number(v), Number(rule.value));
}

function rulesHold(features, rules) {
  // an empty rule list must never fire, or every bar would signal
  if (!Array.isArray(rules) || rules.length === 0) return false;
  return rules.every((r) => ruleHolds(features, r));
}

// Edge-triggered, matching markers.pine: a signal is emitted on the bar where
// a rule list BECOMES true, not on every bar it stays true. The rule lists are
// state predicates ("in an uptrend"), so evaluating them per-bar marked 43% of
// a session long and 98% exit. Still no position state on either side — this
// answers "where could you have entered", not "are you in a trade".
//
// `bars` is one session, so a condition already true on the first bar of the
// day fires there. Pine's [1] reaches into the prior session instead; the
// divergence is one bar at the open and is the same class of known difference
// as the feature recomputation noted above.
function deriveSignals(bars, rules) {
  if (!rules) return [];
  const out = [];
  let prev = { exit: false, long: false, short: false };
  for (const b of bars) {
    const f = b.features;
    const now = {
      exit: rulesHold(f, rules.exit),
      long: rulesHold(f, rules.long_entry),
      short: rulesHold(f, rules.short_entry),
    };
    if (now.exit && !prev.exit) out.push({ kind: "exit", bar: b });
    if (now.long && !prev.long) out.push({ kind: "long", bar: b });
    if (now.short && !prev.short) out.push({ kind: "short", bar: b });
    prev = now;
  }
  return out;
}

// For labeling: pair an entry signal with the first exit signal after it,
// falling back to the last bar of the session if the model never exits.
function pairedExit(signals, entry, bars) {
  const next = signals.find(
    (s) => s.kind === "exit" && new Date(s.bar.ts) > new Date(entry.bar.ts)
  );
  if (next) return next.bar;
  return bars.length ? bars[bars.length - 1] : entry.bar;
}

const SIGNAL_STYLE = {
  long: { text: "L", position: "belowBar", color: T.green, shape: "arrowUp" },
  short: { text: "S", position: "aboveBar", color: T.red, shape: "arrowDown" },
  exit: { text: "X", position: "inBar", color: T.amber, shape: "circle" },
};

// Identifies a signal across the chart, the list, and training_examples.
// Normalised to epoch ms so a `bars.ts` string and a `training_examples.entry_at`
// string for the same minute always produce the same key.
const sigKey = (kind, ts) => `${kind}:${new Date(ts).getTime()}`;

function etTime(ts) {
  return new Date(ts).toLocaleTimeString("en-US", {
    timeZone: "America/New_York",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

// ---------- indicator preview ----------
// Replays one model's rules over a single session's stored bars so the trader
// can see where it would have fired, scroll day to day, and label any signal
// straight into training_examples for the next routine run to learn from.
// EXIT_FEEDBACK — why X markers are inert.
//
// `training_examples` describes a round trip from the trader's point of view:
// entry_at, an optional exit_at, and a Good/Bad quality that judges the TRADE.
// There is no shape in it for "the model exited, and that exit was wrong" —
// the useful critique of an exit is that it came too soon or too late, which
// is a signed distance, not a boolean. Labeling an X through the entry path
// would file a Long example whose entry is the exit bar, which reads as a
// real observation to the routine and is not one.
//
// So exits are shown but not labelable until the schema can carry that. When
// it can, the natural home is this same flow.
function IndicatorPreview({ model }) {
  const [days, setDays] = useState(null);
  const [dayIndex, setDayIndex] = useState(0);
  const [bars, setBars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [labeling, setLabeling] = useState(null); // signal being labeled
  const [note, setNote] = useState("");
  const [saved, setSaved] = useState({}); // key -> quality, for inline feedback
  const [copied, setCopied] = useState(false);
  const [showHidden, setShowHidden] = useState(false); // reveal Bad-tagged signals
  const rowRefs = useRef({}); // key -> row node, so a marker click can scroll to it

  // day list first (ts only — cheap), then the selected day's bars with
  // features on demand, so we never pull ~10k feature blobs at once
  useEffect(() => {
    (async () => {
      try {
        const rows = await fetchAllRows("bars", { select: "ts", orderBy: "ts" });
        const uniq = [...new Set(rows.map((r) => r.ts.slice(0, 10)))].sort();
        setDays(uniq);
        setDayIndex(Math.max(0, uniq.length - 1));
      } catch (e) {
        setError(e.message);
        setLoading(false);
      }
    })();
  }, []);

  const day = days && days[dayIndex];

  useEffect(() => {
    if (!day) return;
    let cancelled = false;
    setLoading(true);
    (async () => {
      const { data, error: err } = await supabase
        .from("bars")
        .select("ts,open,high,low,close,features")
        .gte("ts", `${day}T00:00:00Z`)
        .lt("ts", `${day}T23:59:59.999Z`)
        .order("ts", { ascending: true });
      if (cancelled) return;
      if (err) setError(err.message);
      else {
        setError(null);
        setBars(data);
      }
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [day]);

  // Hydrated from training_examples, not just from what was clicked this mount.
  // `saved` used to be mount-local, so a reload showed every already-labeled
  // signal as unlabeled and a second click filed a duplicate row.
  useEffect(() => {
    if (!day) return;
    let cancelled = false;
    (async () => {
      const { data, error: err } = await supabase
        .from("training_examples")
        .select("entry_at,direction,quality")
        .gte("entry_at", `${day}T00:00:00Z`)
        .lt("entry_at", `${day}T23:59:59.999Z`);
      if (cancelled || err) return;
      setSaved(
        Object.fromEntries(
          data.map((r) => [sigKey(r.direction === "Short" ? "short" : "long", r.entry_at), r.quality])
        )
      );
    })();
    return () => {
      cancelled = true;
    };
  }, [day]);

  const rules = model && model.rules;
  const signals = useMemo(() => deriveSignals(bars, rules), [bars, rules]);

  // A signal already judged Bad is hidden: you've made the call, so it stops
  // competing for attention. Filtered for display only — `signals` stays whole
  // so pairedExit() still walks the model's real sequence.
  const visibleSignals = useMemo(
    () => signals.filter((s) => showHidden || saved[sigKey(s.kind, s.bar.ts)] !== "Bad"),
    [signals, saved, showHidden]
  );
  const hiddenCount = signals.length - visibleSignals.length;

  const chartData = useMemo(
    () =>
      bars.map((b) => ({
        time: Math.floor(new Date(b.ts).getTime() / 1000),
        open: b.open,
        high: b.high,
        low: b.low,
        close: b.close,
      })),
    [bars]
  );

  // Only entry markers carry an `id`, which is what makes them clickable —
  // see EXIT_FEEDBACK below for why exits deliberately don't.
  const markers = useMemo(
    () =>
      visibleSignals.map((s) => ({
        time: Math.floor(new Date(s.bar.ts).getTime() / 1000),
        ...SIGNAL_STYLE[s.kind],
        ...(s.kind === "exit" ? {} : { id: sigKey(s.kind, s.bar.ts) }),
      })),
    [visibleSignals]
  );

  function openLabeler(key) {
    setLabeling(key);
    setNote("");
    const row = rowRefs.current[key];
    if (row) row.scrollIntoView({ behavior: "smooth", block: "center" });
  }

  async function label(signal, quality) {
    // Guarded rather than assumed: `training_examples` is entry-centric, so an
    // exit signal has no honest row shape here — writing one would set
    // entry_at to the moment the model wanted OUT. See EXIT_FEEDBACK.
    if (signal.kind === "exit") return;
    const key = sigKey(signal.kind, signal.bar.ts);
    // Bad = the model should not have signaled here at all, so there is no
    // exit to pair — see exitISO() in the Training Data tab.
    const exitBar = quality === "Bad" ? null : pairedExit(signals, signal, bars);
    const direction = signal.kind === "short" ? "Short" : "Long";
    const tagged = note
      ? `${note} [from preview of model ${model.generated_at}]`
      : `from preview of model ${model.generated_at}`;

    // Re-labeling patches the existing row rather than upserting the whole
    // payload. The row may have been entered by hand with a strategy, a
    // key_level, and a note the trader wrote — an upsert would blank the note
    // and replace a real exit with the model's guessed pairing. Only what this
    // click actually decided gets written.
    const err = saved[key]
      ? (
          await supabase
            .from("training_examples")
            .update({
              quality,
              // Bad has no exit by definition; Good leaves any existing exit
              // alone, since a hand-entered one beats a derived pairing
              ...(quality === "Bad" ? { exit_at: null } : {}),
              ...(note ? { notes: tagged } : {}),
            })
            .eq("entry_at", signal.bar.ts)
            .eq("direction", direction)
        ).error
      : (
          await supabase.from("training_examples").insert({
            entry_at: signal.bar.ts,
            exit_at: exitBar ? exitBar.ts : null,
            ticker: "SPY",
            direction,
            quality,
            notes: tagged,
          })
        ).error;
    if (err) {
      setError(err.message);
      return;
    }
    setSaved({ ...saved, [key]: quality });
    setLabeling(null);
    setNote("");
  }

  async function copyForChat() {
    // only the features the rules actually reference — enough to reason about
    // a signal in conversation without pasting the whole jsonb blob
    const referenced = [
      ...new Set(
        ["long_entry", "short_entry", "exit"].flatMap((k) =>
          (rules[k] || []).map((r) => r.feature)
        )
      ),
    ];
    const payload = {
      day,
      model_generated_at: model.generated_at,
      rules,
      signals: signals.map((s) => ({
        kind: s.kind,
        at: s.bar.ts,
        close: s.bar.close,
        features: Object.fromEntries(
          referenced.map((f) => [f, s.bar.features ? s.bar.features[f] : null])
        ),
      })),
    };
    try {
      await navigator.clipboard.writeText(JSON.stringify(payload, null, 2));
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      setError("Couldn't copy — clipboard blocked by the browser.");
    }
  }

  if (!rules) {
    return (
      <div style={{ fontSize: 12, color: T.dim }}>
        This model has no rules to preview.
      </div>
    );
  }
  if (days === null) {
    return <div style={{ fontSize: 12, color: T.faint }}>Loading sessions…</div>;
  }
  if (days.length === 0) {
    return <div style={{ fontSize: 12, color: T.dim }}>No bars stored yet.</div>;
  }

  const counts = visibleSignals.reduce((acc, s) => {
    acc[s.kind] = (acc[s.kind] || 0) + 1;
    return acc;
  }, {});

  return (
    <div>
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          alignItems: "center",
          gap: 10,
          marginBottom: 12,
        }}
      >
        <button
          onClick={() => setDayIndex((i) => Math.max(0, i - 1))}
          disabled={dayIndex === 0}
          style={{ ...retryBtn, padding: "4px 10px", opacity: dayIndex === 0 ? 0.35 : 1 }}
        >
          ← Prev
        </button>
        <span
          style={{
            fontFamily: T.mono,
            fontSize: 12,
            color: T.ink,
            minWidth: 90,
            textAlign: "center",
          }}
        >
          {day}
        </span>
        <button
          onClick={() => setDayIndex((i) => Math.min(days.length - 1, i + 1))}
          disabled={dayIndex === days.length - 1}
          style={{
            ...retryBtn,
            padding: "4px 10px",
            opacity: dayIndex === days.length - 1 ? 0.35 : 1,
          }}
        >
          Next →
        </button>
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.faint }}>
          {counts.long || 0}L · {counts.short || 0}S · {counts.exit || 0}X
        </span>
        <span style={{ flex: 1 }} />
        <button
          onClick={copyForChat}
          style={{ ...retryBtn, padding: "4px 10px", borderColor: T.amber, color: T.amber }}
        >
          {copied ? "Copied" : "Copy day for chat"}
        </button>
      </div>

      {error && (
        <div style={{ fontSize: 12, color: T.red, marginBottom: 10 }}>{error}</div>
      )}

      <CandleChart data={chartData} markers={markers} onMarkerClick={openLabeler} />

      <div style={{ marginTop: 14 }}>
        <div
          style={{
            fontFamily: T.mono,
            fontSize: 10,
            letterSpacing: "0.14em",
            color: T.amber,
            marginBottom: 8,
          }}
        >
          SIGNALS {loading ? "· loading…" : ""}
          {hiddenCount > 0 && (
            <button
              onClick={() => setShowHidden((v) => !v)}
              style={{
                ...retryBtn,
                padding: "1px 8px",
                marginLeft: 10,
                fontSize: 10,
                letterSpacing: "0.08em",
                color: T.faint,
              }}
            >
              {showHidden ? "hide" : "show"} {hiddenCount} tagged bad
            </button>
          )}
        </div>
        {visibleSignals.length === 0 && !loading && (
          <div style={{ fontSize: 12, color: T.dim }}>
            {signals.length === 0
              ? "No signals fired this session — the rules never all held at once."
              : `All ${signals.length} signals this session are tagged Bad.`}
          </div>
        )}
        {visibleSignals.map((s) => {
          const key = sigKey(s.kind, s.bar.ts);
          const style = SIGNAL_STYLE[s.kind];
          const isLabeling = labeling === key;
          return (
            <div
              key={key}
              ref={(el) => {
                rowRefs.current[key] = el;
              }}
              style={{
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                gap: 10,
                padding: "6px 0",
                borderBottom: `1px solid ${T.panelEdge}`,
                fontSize: 12,
                // the row a marker click just opened, so the eye lands on it
                background: isLabeling ? T.panelEdge : "transparent",
              }}
            >
              <span
                style={{
                  fontFamily: T.mono,
                  fontWeight: 700,
                  color: style.color,
                  width: 14,
                }}
              >
                {style.text}
              </span>
              <span style={{ fontFamily: T.mono, color: T.dim, width: 46 }}>
                {etTime(s.bar.ts)}
              </span>
              <span style={{ fontFamily: T.mono, color: T.faint }}>
                {s.bar.close != null ? s.bar.close.toFixed(2) : "—"}
              </span>
              <span style={{ flex: 1 }} />
              {saved[key] ? (
                <span
                  style={{
                    fontFamily: T.mono,
                    fontSize: 11,
                    color: saved[key] === "Good" ? T.green : T.red,
                  }}
                >
                  saved as {saved[key]}
                </span>
              ) : s.kind === "exit" ? (
                <span style={{ fontFamily: T.mono, fontSize: 11, color: T.faint }}>
                  exit — not labelable yet
                </span>
              ) : isLabeling ? (
                <>
                  <input
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    placeholder="note (optional)"
                    style={{ ...inputStyle, padding: "3px 8px", fontSize: 11, width: 200 }}
                  />
                  <button
                    onClick={() => label(s, "Good")}
                    style={{ ...retryBtn, padding: "3px 10px", borderColor: T.green, color: T.green }}
                  >
                    Good
                  </button>
                  <button
                    onClick={() => label(s, "Bad")}
                    style={{ ...retryBtn, padding: "3px 10px", borderColor: T.red, color: T.red }}
                  >
                    Bad
                  </button>
                  <button
                    onClick={() => {
                      setLabeling(null);
                      setNote("");
                    }}
                    style={{ ...retryBtn, padding: "3px 10px" }}
                  >
                    Cancel
                  </button>
                </>
              ) : (
                <button
                  onClick={() => {
                    setLabeling(key);
                    setNote("");
                  }}
                  style={{ ...retryBtn, padding: "3px 10px", fontSize: 11 }}
                >
                  Label
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const CONFIDENCE_COLOR = { low: T.faint, medium: T.amber, high: T.green };

function RuleList({ title, rules }) {
  return (
    <div>
      <div
        style={{
          fontFamily: T.mono,
          fontSize: 10,
          letterSpacing: "0.12em",
          color: T.faint,
          marginBottom: 6,
        }}
      >
        {title.toUpperCase()}
      </div>
      {rules.length === 0 ? (
        <div style={{ fontSize: 12, color: T.faint }}>No conditions.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
          {rules.map((r, i) => (
            <div key={i} style={{ fontSize: 12, color: T.ink }}>
              <span style={{ fontFamily: T.mono, color: T.amber }}>
                {fLabel(r.feature)} {r.op} {fmtRuleValue(r.value)}
              </span>
              {r.note && <span style={{ color: T.dim }}> — {r.note}</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function ModelCard({ model, expanded, onToggle, onDelete }) {
  const rules = model.rules || {};
  const [pineCopied, setPineCopied] = useState(false);

  async function copyPinescript() {
    try {
      await navigator.clipboard.writeText(model.pinescript);
      setPineCopied(true);
      setTimeout(() => setPineCopied(false), 1500);
    } catch {
      // clipboard failed — the code block is already visible and selectable
    }
  }

  return (
    <div
      style={{
        background: T.panel,
        border: `1px solid ${T.panelEdge}`,
        borderRadius: 10,
        padding: 14,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.dim }}>
          {new Date(model.generated_at).toLocaleString("en-US", {
            month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", hour12: false,
          })}
        </span>
        <span
          style={{
            fontFamily: T.mono, fontSize: 10, letterSpacing: "0.08em",
            color: CONFIDENCE_COLOR[model.confidence] || T.faint,
            border: `1px solid ${CONFIDENCE_COLOR[model.confidence] || T.faint}`,
            borderRadius: 4, padding: "1px 6px",
          }}
        >
          {(model.confidence || "unknown").toUpperCase()} CONFIDENCE
        </span>
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.faint }}>
          {model.examples_used} example{model.examples_used === 1 ? "" : "s"} · {model.bars_analyzed} bars
        </span>
        <span style={{ flex: 1 }} />
        {onToggle && (
          <button onClick={onToggle} style={{ ...retryBtn, padding: "3px 10px", fontSize: 11 }}>
            {expanded ? "Collapse" : "Expand"}
          </button>
        )}
        {onDelete && (
          <button onClick={onDelete} style={{ ...retryBtn, padding: "3px 10px", fontSize: 11 }}>
            Delete
          </button>
        )}
      </div>
      {(expanded === undefined || expanded) && (
        <div style={{ marginTop: 12 }}>
          {model.summary && (
            <div style={{ fontSize: 13, color: T.ink, lineHeight: 1.5, marginBottom: 14 }}>
              {model.summary}
            </div>
          )}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
              gap: 14,
            }}
          >
            <RuleList title="Long entry" rules={rules.long_entry || []} />
            <RuleList title="Short entry" rules={rules.short_entry || []} />
            <RuleList title="Exit" rules={rules.exit || []} />
          </div>
          {model.pinescript && (
            <div style={{ marginTop: 16 }}>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  marginBottom: 6,
                }}
              >
                <div
                  style={{
                    fontFamily: T.mono,
                    fontSize: 10,
                    letterSpacing: "0.12em",
                    color: T.faint,
                  }}
                >
                  PINESCRIPT
                </div>
                <button
                  onClick={copyPinescript}
                  style={{ ...retryBtn, borderColor: T.amber, color: T.amber, padding: "3px 10px", fontSize: 11 }}
                >
                  {pineCopied ? "Copied!" : "Copy"}
                </button>
              </div>
              <pre
                style={{
                  background: T.bg,
                  border: `1px solid ${T.panelEdge}`,
                  borderRadius: 8,
                  padding: 10,
                  fontSize: 11,
                  fontFamily: T.mono,
                  color: T.ink,
                  overflowX: "auto",
                  overflowY: "auto",
                  maxHeight: 280,
                  whiteSpace: "pre",
                  margin: 0,
                }}
              >
                {model.pinescript}
              </pre>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function ModelTab() {
  const [models, setModels] = useState([]);
  const [loadState, setLoadState] = useState("loading");
  const [loadError, setLoadError] = useState(null);
  const [expandedId, setExpandedId] = useState(null);
  const [view, setView] = useState("Rules");

  useEffect(() => {
    (async () => {
      const { data, error } = await supabase
        .from("entry_models")
        .select("*")
        .order("generated_at", { ascending: false });
      if (error) setLoadError(error.message);
      else setModels(data);
      setLoadState("ready");
    })();
  }, []);

  async function deleteModel(id) {
    setLoadError(null);
    const prev = models;
    setModels(models.filter((m) => m.id !== id));
    const { error } = await supabase.from("entry_models").delete().eq("id", id);
    if (error) {
      setLoadError(error.message);
      setModels(prev);
    }
  }

  if (loadState === "loading") {
    return (
      <div style={{ color: T.faint, fontFamily: T.mono, fontSize: 12 }}>
        Loading…
      </div>
    );
  }

  return (
    <div>
      <div style={{ fontSize: 12, color: T.dim, marginBottom: 14 }}>
        Synthesized daily by the routine from the regression output plus your
        Training Data examples. Each run adds a new version below, along
        with a PineScript indicator you can paste into TradingView.
      </div>
      {loadError && (
        <div style={{ fontSize: 12, color: T.red, marginBottom: 12 }}>{loadError}</div>
      )}

      {models.length > 0 && (
        <div style={{ maxWidth: 280, marginBottom: 16 }}>
          <ToggleGroup
            value={view}
            onChange={setView}
            options={["Rules", "Preview"]}
          />
        </div>
      )}

      {models.length > 0 && view === "Preview" && (
        <div>
          <div style={{ fontSize: 12, color: T.dim, marginBottom: 12 }}>
            Latest model replayed over stored bars — scroll sessions, then label
            any signal to file it as a training example.
          </div>
          <IndicatorPreview model={models[0]} />
        </div>
      )}

      {models.length === 0 ? (
        <div style={{ color: T.dim, fontSize: 13 }}>
          No model yet — the daily routine will populate this.
        </div>
      ) : view === "Preview" ? null : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          <ModelCard model={models[0]} onDelete={() => deleteModel(models[0].id)} />
          {models.length > 1 && (
            <div
              style={{
                fontFamily: T.mono,
                fontSize: 10,
                letterSpacing: "0.12em",
                color: T.faint,
                marginTop: 6,
              }}
            >
              PREVIOUS VERSIONS
            </div>
          )}
          {models.slice(1).map((m) => (
            <ModelCard
              key={m.id}
              model={m}
              expanded={expandedId === m.id}
              onToggle={() => setExpandedId(expandedId === m.id ? null : m.id)}
              onDelete={() => deleteModel(m.id)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ---------- main ----------
// Sidebar nav. Items with `children` render as an expandable group; `tab`
// always holds a leaf name, never a group name, so the content switch below
// only ever matches leaves.
const NAV = [
  { label: "Morning Brief" },
  { label: "Dashboard" },
  { label: "Journal" },
  { label: "Modeling", children: ["Charts", "Training Data", "Indicator"] },
  { label: "Resources" },
];


export default function Smaug() {
  const session = useSession();
  const now = useEtClock();
  const countdown = openCountdown(now);
  const [tab, setTab] = useState("Morning Brief");
  const [panels, setPanels] = useState({
    econ: null,
    earnings: null,
    sentiment: null,
    cases: null,
  });
  const [lastRun, setLastRun] = useState(null);

  useEffect(() => {
    if (!session) return;
    (async () => {
      const { data } = await supabase
        .from("daily_briefs")
        .select("*")
        .order("generated_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (data) {
        setPanels({
          econ: data.econ || null,
          earnings: data.earnings || null,
          sentiment: data.sentiment || null,
          cases: data.cases || null,
        });
        setLastRun(new Date(data.generated_at));
      }
    })();
  }, [session]);

  return (
    <AuthGate>
    <div
      style={{
        minHeight: "100vh",
        background: T.bg,
        fontFamily: T.sans,
        color: T.ink,
        padding: "12px 18px 40px",
      }}
    >
      <style>{`
        @keyframes pulse { 0%,100%{opacity:.25} 50%{opacity:1} }
        button:focus-visible, a:focus-visible { outline: 2px solid ${T.amber}; outline-offset: 2px; }
        input:focus, select:focus { border-color: ${T.amber} !important; }
        @media (prefers-reduced-motion: reduce) { * { animation: none !important; } }
      `}</style>

      {/* header: just the sign-out button. The logo and wordmark used to live
          here — the logo absolutely positioned so it could overhang into the
          sidebar, the wordmark centered — which cost ~94px of full-width page
          height. Both now stack at the top of the sidebar column instead, so
          content starts at the very top of the page. */}
        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            marginBottom: 10,
          }}
        >
          {session && (
            <button
              onClick={() => supabase.auth.signOut()}
              style={{ ...retryBtn, padding: "3px 10px", fontSize: 11, flexShrink: 0 }}
            >
              Sign out ({session.user.email})
            </button>
          )}
        </div>

        <div style={{ display: "flex", gap: 28, alignItems: "flex-start" }}>
          {/* left sidebar: brand, date, session strip, nav */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 2,
              width: 200,
              flexShrink: 0,
            }}
          >
            <img
              src={LOGO}
              alt="Smaug logo"
              width={200}
              height={200}
              style={{ display: "block" }}
            />
            {/* sized to the logo's width rather than a fixed height, so the
                wordmark and the dragon share one left and right edge */}
            <img
              src={WORDMARK}
              alt="SMAUG"
              style={{ display: "block", width: "100%", height: "auto" }}
            />
            <div
              style={{
                width: "100%",
                height: 2,
                background: T.amber,
                margin: "7px 0 14px",
              }}
            />
            <div
              style={{
                fontSize: 13,
                color: T.dim,
                fontWeight: 300,
                marginBottom: 6,
              }}
            >
              {todayLabel()}
            </div>
            <div
              style={{
                display: "inline-flex",
                flexWrap: "wrap",
                alignItems: "center",
                gap: 18,
                fontFamily: T.mono,
                fontSize: 12,
                color: T.dim,
                borderTop: `1px solid ${T.panelEdge}`,
                borderBottom: `1px solid ${T.panelEdge}`,
                padding: "6px 24px 6px 2px",
                marginBottom: 10,
              }}
            >
              <span>
                ET{" "}
                <span style={{ color: T.ink }}>
                  {now.toLocaleTimeString("en-US", { hour12: false })}
                </span>
              </span>
              <span style={{ color: countdown.tone }}>{countdown.label}</span>
            </div>
            {NAV.map((item) => {
              // children are always listed; a group header is highlighted when
              // one of them is active and selects the first child when clicked
              const active = item.children
                ? item.children.includes(tab)
                : tab === item.label;
              return (
                <div key={item.label}>
                  <button
                    onClick={() =>
                      setTab(item.children ? item.children[0] : item.label)
                    }
                    style={{
                      ...navBtnBase,
                      background:
                        active && !item.children ? "rgba(224,123,42,0.1)" : "transparent",
                      borderLeft:
                        active && !item.children
                          ? `2px solid ${T.amber}`
                          : "2px solid transparent",
                      color: active ? T.ink : T.faint,
                      fontSize: 17,
                      height: 48,
                      width: "100%",
                    }}
                  >
                    {item.label.toUpperCase()}
                  </button>
                  {item.children &&
                    item.children.map((child) => {
                      const childActive = tab === child;
                      return (
                        <button
                          key={child}
                          onClick={() => setTab(child)}
                          style={{
                            ...navBtnBase,
                            background: childActive
                              ? "rgba(224,123,42,0.1)"
                              : "transparent",
                            borderLeft: childActive
                              ? `2px solid ${T.amber}`
                              : "2px solid transparent",
                            color: childActive ? T.ink : T.faint,
                            fontFamily: T.mono,
                            fontSize: 11,
                            padding: "0 12px 0 26px",
                            height: 30,
                            width: "100%",
                          }}
                        >
                          {child.toUpperCase()}
                        </button>
                      );
                    })}
                </div>
              );
            })}
          </div>

          {/* tab content */}
          <div style={{ flex: 1, minWidth: 0 }}>
        {tab === "Morning Brief" && (
          <MorningBriefTab panels={panels} lastRun={lastRun} />
        )}
        {tab === "Dashboard" && <DashboardTab />}
        {tab === "Journal" && <JournalTab />}
        {tab === "Charts" && (
          <div style={{ maxWidth: 1100, margin: "0 auto" }}>
            <TechnicalsTab />
          </div>
        )}
        {tab === "Training Data" && <TrainingDataTab />}
        {tab === "Indicator" && <ModelTab />}
        {tab === "Resources" && <ResourcesTab />}
          </div>
        </div>
    </div>
    </AuthGate>
  );
}
